set cspu_max_dt = (select max(local_date) as max_date from srdi_mart.dws_sr_data_warehouse_tc_pb_cspu_level_1d)
;

--sql_divide_splitter--
CREATE TEMPORARY VIEW shop_type_${grass_region_without_quote} AS
select
     shop_id
    ,type as shop_scs_type
from regds_listing.dim_scs_shop_list_df
where grass_region in (${grass_region}) and type in ('scs-local','scs-cb')
;
--sql_divide_splitter--
CREATE TEMPORARY VIEW cheapest_model_list_${grass_region_without_quote} AS
select
     local_hour as cheapest_hour
    ,cspu_id
    ,model_id
    ,item_id
    ,a.shop_id
    ,shop_scs_type
from(
    SELECT
         cspu_id
        ,model_id
        ,item_id
        ,shop_id
        ,local_hour
    FROM srdi_mart.dim_sr_data_warehouse_pb_one_variation_model_analysis_hf
    WHERE grass_region = ${grass_region} AND local_date = ${local_date}
) a
left join shop_type_${grass_region_without_quote} b on a.shop_id=b.shop_id
;

--sql_divide_splitter--
create temporary view    cheapest_item_list_${grass_region_without_quote}
as
select  cheapest_hour
        ,item_id
        ,shop_id
        ,max(shop_scs_type) as shop_scs_type
from cheapest_model_list_${grass_region_without_quote}
group by cheapest_hour, item_id, shop_id
;

--sql_divide_splitter--
create temporary view       dim_user_exp_${grass_region_without_quote}
as
select  user_id
        ,T1.exp_group_id
        ,exp_group_type
from    (
    select  group_id as exp_group_id
            ,layer_id
            ,case   when group_id in (40252) then 'control'
                    else 'treatment'
             end as exp_group_type
    from    abtest.shopee_experiment_admin_db__group_dimension_tab__reg_continuous_s0_live a
    where   group_id in (452526, 452527, 452528, 452529, 452530, 452531, 452532, 452533, 452534, 452535, 452536, 452537, 452538, 452539, 452540, 452541, 452542, 452543, 40252)
    group by 1, 2
) as T1
inner join (
    select  user_id
            ,exp_group_id
    from    srdi_mart.dim_sr_data_warehouse_abtest_user_group
    where   grass_region in (${grass_region})
      and   local_date = ${local_date}
      and   is_assignment_log = 1
) as T2
on      T1.exp_group_id = T2.exp_group_id
group by 1, 2, 3
;

--sql_divide_splitter--
create temporary view     cspu_label_avg_${grass_region_without_quote}
as
select  cspu_id
        ,avg(order_cnt) as cspu_l1d_order_cnt
from    srdi_mart.dws_sr_data_warehouse_tc_pb_cspu_level_1d
where   grass_region IN (${grass_region})
  and   local_date BETWEEN date_sub(${cspu_max_dt}, 6)
  and   ${cspu_max_dt}
group by 1
;

--sql_divide_splitter--
create temporary view    traffic_data_item_${grass_region_without_quote}
as
select  a.is_item_card
        ,a.user_id
        ,a.item_id
        ,a.model_id
        ,a.is_ads
        ,a.mapping_general
        ,if(b.item_id is not null, 1, 0) as is_cheapest_item
        ,if(b1.model_id is not null, 1, 0) as is_cheapest_model
        ,imp_cnt
        ,click_cnt
        ,order_cnt
from    (
    select  *
    from    srdi_mart.dws_sr_data_warehouse_tc_pb_basic_aggr_1d
    where   grass_region = ${grass_region}
      and   local_date = ${local_date}
      and   mapping_general in ('__ALL__')
) as a
left join cheapest_item_list_${grass_region_without_quote} b
on      a.item_id = b.item_id
  and   a.local_hour = b.cheapest_hour
left join cheapest_model_list_${grass_region_without_quote} b1
on     a.item_id = b1.item_id
  and   a.model_id = b1.model_id
  and   a.local_hour = b1.cheapest_hour
;

--sql_divide_splitter--
create temporary view    model_exp_result_${grass_region_without_quote}
as
select  item_id
        ,sum(if(exp_group_type = 'treatment', imp_cnt, 0)) as treatment_imp_cnt
        ,sum(if(exp_group_type = 'control', imp_cnt, 0)) as control_imp_cnt
        ,sum(if(exp_group_type = 'treatment', click_cnt, 0)) as treatment_click_cnt
        ,sum(if(exp_group_type = 'control', click_cnt, 0)) as control_click_cnt
        ,sum(if(exp_group_type = 'treatment', orde_cnt, 0)) as treatment_order_cnt
        ,sum(if(exp_group_type = 'control', orde_cnt, 0)) as control_order_cnt
        ,sum(if(exp_group_type = 'treatment' and is_cheapest_item = 1, imp_cnt, 0)) as treatment_cheapest_imp_cnt
        ,sum(if(exp_group_type = 'control' and is_cheapest_item = 1, imp_cnt, 0)) as control_cheapest_imp_cnt
        ,sum(if(exp_group_type = 'treatment' and is_cheapest_item = 1, orde_cnt, 0)) as treatment_cheapest_order_cnt
        ,sum(if(exp_group_type = 'control' and is_cheapest_item = 1, orde_cnt, 0)) as control_cheapest_order_cnt
        ,1.000*sum(if(exp_group_type = 'treatment' and is_cheapest_item = 1, orde_cnt, 0)) /sum(if(exp_group_type = 'treatment' and is_cheapest_item = 1, imp_cnt, 0)) as trmt_ctrcr
        ,1.000*sum(if(exp_group_type = 'control' and is_cheapest_item = 1, orde_cnt, 0)) /sum(if(exp_group_type = 'control' and is_cheapest_item = 1, imp_cnt, 0)) as control_ctrcr
from    (
    select  a.user_id
            ,b.exp_group_id
            ,b.exp_group_type
            ,item_id
            ,is_cheapest_item
            ,is_cheapest_model
            ,sum(imp_cnt) as imp_cnt
            ,sum(click_cnt) as click_cnt
            ,sum(order_cnt) as orde_cnt
    from    traffic_data_item_${grass_region_without_quote} a
    inner join dim_user_exp_${grass_region_without_quote} b
    on      a.user_id = b.user_id
    group by 1, 2, 3, 4, 5, 6
)
group by 1
;

--sql_divide_splitter--
insert overwrite table ${schema}.ads_sr_data_warehouse_tc_pb_qc_model_level_1d
partition (grass_region = ${grass_region}, local_date = ${local_date})
select  T1.cspu_id
        ,T1.shop_id
        ,T1.item_id
        ,T1.model_id
        ,T1.model_type
        ,coalesce(T3.avg_model_order_cnt, 0) as avg_model_order_cnt_7d
        ,coalesce(T2.cspu_l1d_order_cnt, 0) as avg_cspu_order_cnt_7d
        ,coalesce(T4.treatment_imp_cnt, 0) as treatment_imp_cnt
        ,coalesce(T4.trmt_ctrcr, 0) as trmt_ctrcr
        ,coalesce(T4.control_ctrcr, 0) as control_ctrcr
        ,if(coalesce(T4.control_ctrcr, 0) = 0, 0, (1.00*coalesce(T4.trmt_ctrcr, 0)/ coalesce(T4.control_ctrcr, 0) -1)) as item_ctrcr_trmt_vs_control
from    (
    select  cspu_id
            ,shop_id
            ,item_id
            ,model_id
            ,max(model_type) as model_type
    from    (
        select  cspu_id
                ,shop_id
                ,item_id
                ,model_id
                ,case   when shop_scs_type in ('scs-local', 'scs-cb') then 'scs cheapest'
                        else 'non-scs cheapest'
                 end as model_type
        from    cheapest_model_list_${grass_region_without_quote}
    )
    group by 1, 2, 3, 4
) as T1
left join cspu_label_avg_${grass_region_without_quote} as T2
on      T1.cspu_id = T2.cspu_id
left join (
    select  cspu_id
            ,model_id
            ,item_id
            ,shop_id
            ,sum(model_order_cnt)/count(distinct local_date) as avg_model_order_cnt
    from    srdi_mart.dws_sr_data_warehouse_tc_pb_one_variation_model_day_level_analysis_1d
    where   grass_region IN (${grass_region})
      and   local_date  BETWEEN date_sub(${local_date}, 6)
      and   ${local_date}
    group by cspu_id, model_id, item_id, shop_id
) as T3
on      T1.model_id = T3.model_id
 and    T1.cspu_id = T3.cspu_id
left join model_exp_result_${grass_region_without_quote} as T4
on      T1.item_id = T4.item_id
;
